def solve_n6():
    target_sums = set(range(1, 16))
    for a1 in range(-5, 5):
        a2 = 1 - a1
        if a2 <= a1: continue
        for a3 in range(a2 + 1, 15):
            for a4 in range(a3 + 1, 15):
                for a5 in range(a4 + 1, 15):
                    a6 = 15 - a5
                    if a6 <= a5: continue
                    a = [a1, a2, a3, a4, a5, a6]
                    sums = []
                    for i in range(6):
                        for j in range(i + 1, 6):
                            sums.append(a[i] + a[j])
                    if len(set(sums)) == 15 and set(sums) == target_sums:
                        return a
    return None

print(solve_n6())

